/// The code, one action per digit.
const CODE: [&str; 4] = ["a", "c", "b", "c"];

fn update(scene: &mut GameScene<'_>, _time: &FrameTime) {
    if scene.counter_or("unlocked", 0) == 1 {
        return;
    }
    let Some(key) = ["a", "b", "c"].into_iter().find(|key| scene.pressed(key))
    else {
        return;
    };
    let progress = scene.counter_or("progress", 0);
    if key != CODE[progress as usize] {
        scene.set_counter("progress", 0);
        scene.add_to_counter("mistakes", 1);
        return;
    }
    scene.set_counter("progress", progress + 1);
    if progress + 1 == CODE.len() as i32 {
        scene.set_counter("unlocked", 1);
        scene.set_hud("Message", |hud| hud.text = "Unlocked".into());
    }
}
